export interface ConnectorConfig {
  /** Brevo API key from environment variable BREVO_API_KEY */
  brevoApiKey: string
  /** Brevo list ID to subscribe the contact to */
  listId: number
  /** Typeform field ID for the email question */
  emailFieldId: string
  /** Typeform field ID for the first name question */
  firstNameFieldId: string
  /** Typeform field ID for the last name question */
  lastNameFieldId: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface BrevoContactResult {
  id: number
}

async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<BrevoContactResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required config
  if (!config.brevoApiKey) throw new Error('Missing required config: brevoApiKey')
  if (!config.listId) throw new Error('Missing required config: listId')
  if (!config.emailFieldId) throw new Error('Missing required config: emailFieldId')
  if (!config.firstNameFieldId) throw new Error('Missing required config: firstNameFieldId')
  if (!config.lastNameFieldId) throw new Error('Missing required config: lastNameFieldId')

  // Validate payload structure
  if (!payload.form_response?.answers?.length) {
    throw new Error('Invalid payload: missing form_response.answers')
  }

  // Extract answers by field ID
  const answers = payload.form_response.answers
  const emailAnswer = answers.find(a => a.field.id === config.emailFieldId)
  const firstNameAnswer = answers.find(a => a.field.id === config.firstNameFieldId)
  const lastNameAnswer = answers.find(a => a.field.id === config.lastNameFieldId)

  if (!emailAnswer?.email) {
    throw new Error(`Required email field (id: ${config.emailFieldId}) not found or empty in payload`)
  }
  if (!firstNameAnswer?.text) {
    throw new Error(`Required first name field (id: ${config.firstNameFieldId}) not found or empty in payload`)
  }
  if (!lastNameAnswer?.text) {
    throw new Error(`Required last name field (id: ${config.lastNameFieldId}) not found or empty in payload`)
  }

  // Build Brevo request body
  const brevoBody = {
    email: emailAnswer.email,
    attributes: {
      FNAME: firstNameAnswer.text,
      LNAME: lastNameAnswer.text
    },
    listIds: [config.listId]
  }

  // Call Brevo API
  const response = await fetchImpl('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.brevoApiKey,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    },
    body: JSON.stringify(brevoBody)
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} at POST https://api.brevo.com/v3/contacts - ${errorText}`)
  }

  const result = await response.json() as BrevoContactResult
  return result
}

